namespace BG3PakViewer.Contracts;

/// <summary>
///     Exports the content generated by a preview to a folder the user picks. The files do not have to
///     exist in the package, so it serves content such as the sliced icons of an atlas or the layers of
///     a virtual texture.
/// </summary>
public interface IPreviewExportService
{
    /// <summary>
    ///     Asks the user for a target folder and writes the given files there.
    /// </summary>
    /// <param name="files">The files to export.</param>
    Task ExportAsync(IReadOnlyList<PreviewExportFile> files);
}

/// <summary>
///     A single file of a preview export together with the name it is written to.
/// </summary>
/// <param name="FileName">The name of the file, including its extension.</param>
/// <param name="OpenAsync">Opens the content of the file to be written.</param>
public record PreviewExportFile(string FileName, Func<Task<Stream>> OpenAsync);